{
  "pdf_page": 195,
  "book_page": 165,
  "verified_by": "claude-opus-5",
  "verified_on": "2026-09-05",
  "entries": [
    {
      "entry": 0,
      "root": "Gh.r.f",
      "verdict": "confirmed",
      "modern_form": "Arabic root غ-ر-ف, verb غَرَفَ (ḡarafa) 'to scoop, lade out (water)'",
